package com.college.attendance.mobile.ui;
import android.content.*; import android.os.Bundle; import android.view.View; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.college.attendance.mobile.R; import com.college.attendance.mobile.api.*; import com.college.attendance.mobile.model.*; import com.google.gson.Gson; import java.util.*; import retrofit2.*;
public class DashboardActivity extends AppCompatActivity {
 LinearLayout actions; TextView title,welcome,out; String role;
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_dashboard);title=findViewById(R.id.title);welcome=findViewById(R.id.welcome);out=findViewById(R.id.output);actions=findViewById(R.id.actions); role=getSharedPreferences("auth",0).getString("role","STUDENT");String name=getSharedPreferences("auth",0).getString("name","");title.setText(role+" MODULE");welcome.setText("Welcome, "+name+"\nAccess is based on your role.");build();}
 void btn(String text,View.OnClickListener l){Button b=new Button(this);b.setText(text);b.setOnClickListener(l);actions.addView(b);}
 void build(){if(role.equals("STUDENT")){btn("1. Mark Attendance (Face)",v->loadActive());btn("Register / Update Face",v->registerFace());btn("2. View Attendance",v->studentAttendance());btn("3. Assignments",v->assignments());btn("4. Feedback / Complaints",v->complaintDialog());} else if(role.equals("TEACHER")){btn("1. Create Attendance Session",v->createSession());btn("2. View Sessions",v->teacherSessions());btn("3. View Student Attendance",v->teacherSessions());btn("4. Assignments",v->toast("Use backend /api/academic/assignments endpoints; add form here."));btn("5. Doubts / Complaints",v->toast("Use /api/academic/complaints endpoints."));} else {btn("1. Search & View Students",v->hodStudents());btn("2. Monitoring / Analytics",v->analytics());btn("3. Complaints & Feedback",v->toast("Use /api/hod/complaints."));btn("4. User Management",v->toast("Use /api/hod/user/{id}/disable."));}}
 void loadActive(){ApiClient.get(this).profile().enqueue(new Callback<Student>(){public void onResponse(Call<Student> c,Response<Student> r){if(!r.isSuccessful()||r.body()==null){toast("Student profile unavailable");return;}Long sid=r.body().id;ApiClient.get(DashboardActivity.this).activeSession().enqueue(new Callback<Session>(){public void onResponse(Call<Session> c,Response<Session> rr){if(rr.isSuccessful()&&rr.body()!=null){Intent i=new Intent(DashboardActivity.this,FaceCaptureActivity.class);i.putExtra("studentId",sid);i.putExtra("sessionId",rr.body().id);startActivity(i);}else toast("No active session for your section");}public void onFailure(Call<Session> c,Throwable t){toast(t.getMessage());}});}public void onFailure(Call<Student> c,Throwable t){toast(t.getMessage());}});}
 void registerFace(){ApiClient.get(this).profile().enqueue(new Callback<Student>(){public void onResponse(Call<Student> c,Response<Student> r){if(r.isSuccessful()&&r.body()!=null){Intent i=new Intent(DashboardActivity.this,FaceCaptureActivity.class);i.putExtra("studentId",r.body().id);i.putExtra("register",true);startActivity(i);}else toast("Student profile unavailable");}public void onFailure(Call<Student> c,Throwable t){toast(t.getMessage());}});}
 void studentAttendance(){ApiClient.get(this).studentAttendance().enqueue(new Callback<List<AttendanceRecord>>(){public void onResponse(Call<List<AttendanceRecord>> c,Response<List<AttendanceRecord>> r){out.setText(r.isSuccessful()?new Gson().toJson(r.body()):"Could not load attendance");}public void onFailure(Call<List<AttendanceRecord>> c,Throwable t){toast(t.getMessage());}});}
 void assignments(){toast("Assignments API is implemented in backend. Add RecyclerView/form UI as the next UI task.");}
 void createSession(){ApiClient.get(this).subjects().enqueue(new Callback<List<Subject>>(){public void onResponse(Call<List<Subject>> c,Response<List<Subject>> r){if(r.isSuccessful()&&r.body()!=null&&!r.body().isEmpty()){Subject s=r.body().get(0);Map<String,Object> m=new HashMap<>();m.put("subjectId",s.id);m.put("section",s.section);m.put("durationMinutes",15);ApiClient.get(DashboardActivity.this).createSession(m).enqueue(new Callback<Session>(){public void onResponse(Call<Session> c,Response<Session> r){out.setText(r.isSuccessful()?new Gson().toJson(r.body()):"Session create failed");}public void onFailure(Call<Session> c,Throwable t){toast(t.getMessage());}});}else toast("No subject assigned");}public void onFailure(Call<List<Subject>> c,Throwable t){toast(t.getMessage());}});}
 void teacherSessions(){ApiClient.get(this).teacherSessions().enqueue(new Callback<List<Session>>(){public void onResponse(Call<List<Session>> c,Response<List<Session>> r){out.setText(r.isSuccessful()?new Gson().toJson(r.body()):"Could not load sessions");}public void onFailure(Call<List<Session>> c,Throwable t){toast(t.getMessage());}});}
 void hodStudents(){ApiClient.get(this).hodStudents().enqueue(new Callback<List<Student>>(){public void onResponse(Call<List<Student>> c,Response<List<Student>> r){out.setText(r.isSuccessful()?new Gson().toJson(r.body()):"Could not load students");}public void onFailure(Call<List<Student>> c,Throwable t){toast(t.getMessage());}});}
 void analytics(){ApiClient.get(this).analytics().enqueue(new Callback<Map<String,Object>>(){public void onResponse(Call<Map<String,Object>> c,Response<Map<String,Object>> r){out.setText(r.isSuccessful()?new Gson().toJson(r.body()):"Analytics failed");}public void onFailure(Call<Map<String,Object>> c,Throwable t){toast(t.getMessage());}});}
 void complaintDialog(){EditText e=new EditText(this);e.setHint("Complaint / feedback");new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Feedback / Complaint").setView(e).setPositiveButton("Submit",(d,w)->toast("Connect form to POST /api/academic/complaints")).setNegativeButton("Cancel",null).show();}
 void toast(String s){Toast.makeText(this,s==null?"Error":s,Toast.LENGTH_LONG).show();}
}
